<div x-show="proposals.length" class="space-y-4"><h2 class="text-xl font-semibold">Riwayat Usulan</h2><template x-for="proposal in proposals" :key="proposal.id"><x-card><div class="px-6 flex flex-wrap justify-between items-start gap-3"><div><h3 class="text-lg font-semibold" x-text="proposal.title"></h3><p class="text-sm text-muted-foreground">Pembimbing: <span x-text="person(proposal.proposed_supervisor)"></span></p></div><x-badge style="secondary" ::class="badge(proposal.supervisor_approval_status)" x-text="proposal.supervisor_approval_status" /></div><div class="px-6 space-y-3">@foreach(['description'=>'Deskripsi','problem_statement'=>'Rumusan Masalah','scope'=>'Ruang Lingkup'] as $key=>$label)<div x-show="proposal.{{ $key }}"><div class="text-xs text-muted-foreground uppercase font-semibold mb-1">{{ $label }}</div><p class="text-sm whitespace-pre-wrap" x-text="proposal.{{ $key }}"></p></div>@endforeach<x-alert style="danger" title="Alasan Penolakan" x-show="proposal.supervisor_approval_status==='REJECTED' && proposal.rejection_reason"><span x-text="proposal.rejection_reason"></span></x-alert><div class="text-xs text-muted-foreground">Dikirim: <span x-text="date(proposal.created_at)"></span></div></div><div class="px-6 flex justify-end gap-2" x-show="canEdit(proposal)"><x-btn style="outline" size="sm" @click="cancel(proposal)" x-bind:disabled="saving"><x-capstone::icon name="Trash2" />Batalkan</x-btn><x-btn style="outline" size="sm" @click="edit(proposal)" x-bind:disabled="saving"><x-capstone::icon name="PenLine" /><span x-text="proposal.supervisor_approval_status==='REJECTED'?'Ubah & Kirim Ulang':'Ubah'"></span></x-btn></div></x-card></template></div>
